		t.Fatalf("permission request = sandbox=%q permissions=%q policy=%+v", req.Sandbox, req.Permissions, req.Policy)
	}
	for _, tool := range []string{"write", "edit", "patch", "bash", "shell"} {
		if req.Policy.Tools[tool] != "deny" {
